/* Three original HTSE practice banks. Correct answers appear only in the practice/mock client; official scoring remains server-side. */
window.HTSE_QUESTION_BANK = Object.freeze({"nursing":{"label":"Nursing","description":"Common five-subject healthcare syllabus at foundational nursing level. Original practice questions with 100 MCQs and 20 questions per subject.","difficulty_label":"Foundational","subjects":[{"key":"anatomy","label":"Anatomy","question_count":20},{"key":"physiology","label":"Physiology","question_count":20},{"key":"biochemistry","label":"Biochemistry","question_count":20},{"key":"healthcare_it","label":"Healthcare IT","question_count":20},{"key":"oet_english","label":"OET-style Healthcare English","question_count":20}],"questions":[{"id":"NUR-001","question":"Which description matches the standard anatomical position?","options":["Standing upright, facing forward, arms at sides and palms facing forward","Standing with palms facing backward","Supine with arms crossed","Standing with the head turned sideways"],"answer":0,"explanation":"The anatomical position is upright and forward-facing, with arms at the sides and palms anterior.","topic":"Anatomical position","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-002","question":"Which plane divides the body into left and right portions?","options":["Transverse","Sagittal","Coronal","Oblique"],"answer":1,"explanation":"A sagittal plane separates left and right portions; a midsagittal plane creates equal halves.","topic":"Body planes","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-003","question":"Which bone forms the upper arm?","options":["Radius","Ulna","Humerus","Clavicle"],"answer":2,"explanation":"The humerus is the long bone of the upper arm.","topic":"Skeletal system","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-004","question":"Which chamber receives oxygenated blood from the pulmonary veins?","options":["Right atrium","Right ventricle","Left ventricle","Left atrium"],"answer":3,"explanation":"Pulmonary veins return oxygenated blood to the left atrium.","topic":"Cardiac anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-005","question":"Where does most gas exchange occur in the lungs?","options":["Alveoli","Trachea","Main bronchi","Pleural cavity"],"answer":0,"explanation":"Alveoli provide a thin, extensive surface for oxygen and carbon dioxide exchange.","topic":"Respiratory anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-006","question":"What is the functional unit of the kidney?","options":["Neuron","Nephron","Alveolus","Hepatocyte"],"answer":1,"explanation":"Each nephron filters blood and modifies filtrate to form urine.","topic":"Renal anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-007","question":"Which organ produces bile?","options":["Pancreas","Stomach","Liver","Gallbladder"],"answer":2,"explanation":"The liver produces bile; the gallbladder stores and concentrates it.","topic":"Digestive anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-008","question":"The thyroid gland is primarily located:","options":["Behind the kidneys","Inside the pelvis","Within the thoracic cavity","In the anterior neck"],"answer":3,"explanation":"The thyroid lies in the anterior neck, in front of the trachea.","topic":"Endocrine anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-009","question":"Where are most blood cells formed in healthy adults?","options":["Red bone marrow","Gallbladder","Thyroid follicles","Pleural membrane"],"answer":0,"explanation":"Haematopoiesis occurs mainly in red bone marrow.","topic":"Blood and marrow","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-010","question":"Which structure protects the brain?","options":["Rib cage","Cranium","Pelvic girdle","Vertebral disc"],"answer":1,"explanation":"The cranial bones form a protective enclosure around the brain.","topic":"Nervous anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-011","question":"Which muscle is the main muscle of quiet inspiration?","options":["Rectus abdominis","Biceps brachii","Diaphragm","Trapezius"],"answer":2,"explanation":"Diaphragm contraction increases thoracic volume during inspiration.","topic":"Muscle anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-012","question":"Which vessels normally carry blood away from the heart?","options":["Veins","Venules","Lymphatics","Arteries"],"answer":3,"explanation":"Arteries carry blood away from the heart; oxygen content depends on the circulation.","topic":"Vascular anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-013","question":"Which organ is the main site of nutrient absorption?","options":["Small intestine","Stomach","Oesophagus","Large intestine"],"answer":0,"explanation":"Most digestion and nutrient absorption occur in the small intestine.","topic":"Gastrointestinal anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-014","question":"Which structure carries urine from a kidney to the bladder?","options":["Urethra","Ureter","Renal artery","Vena cava"],"answer":1,"explanation":"The ureter transports urine from the renal pelvis to the urinary bladder.","topic":"Urinary anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-015","question":"Which layer contains most of the blood vessels and sensory structures of the skin?","options":["Stratum corneum","Epidermis","Dermis","Nail plate"],"answer":2,"explanation":"The dermis contains vessels, nerves, glands and connective tissue.","topic":"Skin","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-016","question":"Which organ filters lymph from tissues?","options":["Thymus only","Pancreas","Adrenal gland","Lymph nodes"],"answer":3,"explanation":"Lymph nodes filter lymph and support immune surveillance.","topic":"Lymphatic anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-017","question":"Where does fertilisation most commonly occur?","options":["Uterine tube","Cervix","Vagina","Uterine cavity"],"answer":0,"explanation":"Fertilisation usually occurs in the ampullary region of the uterine tube.","topic":"Reproductive anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-018","question":"Which transparent structure at the front of the eye helps refract light?","options":["Retina","Cornea","Optic nerve","Sclera"],"answer":1,"explanation":"The cornea provides much of the eye's initial refractive power.","topic":"Eye anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-019","question":"Which vessel brings nutrient-rich blood from the intestines to the liver?","options":["Pulmonary artery","Renal vein","Portal vein","Carotid artery"],"answer":2,"explanation":"The hepatic portal vein carries absorbed nutrients from the gastrointestinal tract to the liver.","topic":"Liver anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-020","question":"Which structure connects one bone to another at a joint?","options":["Tendon","Fascia","Cartilage only","Ligament"],"answer":3,"explanation":"Ligaments connect bone to bone and help stabilise joints.","topic":"Joint anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"NUR-021","question":"The primary function of the left ventricle is to:","options":["Pump blood into systemic circulation","Pump blood to the lungs","Receive blood from the vena cava","Store blood returning from the lungs"],"answer":0,"explanation":"The left ventricle ejects oxygenated blood into the aorta for systemic circulation.","topic":"Cardiovascular function","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-022","question":"Which structure normally initiates the heartbeat?","options":["AV node","Sinoatrial node","Bundle of His","Purkinje fibres"],"answer":1,"explanation":"The sinoatrial node is the usual pacemaker of the heart.","topic":"Heart rhythm","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-023","question":"Systolic blood pressure is measured during:","options":["Ventricular relaxation","Atrial filling only","Ventricular contraction","Venous return"],"answer":2,"explanation":"Systolic pressure is the peak arterial pressure during ventricular systole.","topic":"Blood pressure","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-024","question":"Oxygen moves from alveoli into pulmonary capillary blood mainly by:","options":["Active transport","Filtration","Osmosis","Diffusion down a partial-pressure gradient"],"answer":3,"explanation":"Oxygen diffuses from higher alveolar partial pressure to lower blood partial pressure.","topic":"Respiratory function","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-025","question":"Antidiuretic hormone generally causes the kidneys to:","options":["Increase water reabsorption","Excrete more water","Reduce water reabsorption","Stop filtration completely"],"answer":0,"explanation":"ADH increases water reabsorption in collecting ducts, concentrating urine.","topic":"Kidney function","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-026","question":"Which hormone lowers blood glucose by promoting cellular uptake and storage?","options":["Glucagon","Insulin","Cortisol","Adrenaline"],"answer":1,"explanation":"Insulin promotes glucose uptake in responsive tissues and supports glycogen synthesis.","topic":"Glucose regulation","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-027","question":"Which brain region is a major centre for temperature regulation?","options":["Cerebellum","Medulla only","Hypothalamus","Occipital lobe"],"answer":2,"explanation":"The hypothalamus integrates signals and coordinates thermoregulatory responses.","topic":"Thermoregulation","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-028","question":"A negative-feedback mechanism usually:","options":["Amplifies the original change","Prevents all hormone release","Works only during sleep","Opposes a deviation from a set range"],"answer":3,"explanation":"Negative feedback counteracts a change and helps maintain internal stability.","topic":"Homeostasis","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-029","question":"Peristalsis is best described as:","options":["Wave-like contractions that move contents through the gut","Enzyme secretion by the liver","Filtration of blood in kidneys","Gas exchange in alveoli"],"answer":0,"explanation":"Coordinated smooth-muscle contractions propel gastrointestinal contents.","topic":"Digestion","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-030","question":"The basic signalling cell of the nervous system is the:","options":["Osteocyte","Neuron","Erythrocyte","Hepatocyte"],"answer":1,"explanation":"Neurons receive and transmit electrical and chemical signals.","topic":"Nervous function","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-031","question":"The normal arterial blood pH range is approximately:","options":["6.8–7.0","7.00–7.20","7.35–7.45","7.60–7.80"],"answer":2,"explanation":"Arterial blood pH is normally maintained within a narrow range around 7.4.","topic":"Acid-base balance","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-032","question":"Most oxygen in blood is transported:","options":["Dissolved freely in plasma","Attached to platelets","As bicarbonate","Bound to haemoglobin"],"answer":3,"explanation":"Haemoglobin in red blood cells carries the large majority of blood oxygen.","topic":"Blood oxygen","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-033","question":"Stimulation of the sympathetic nervous system commonly:","options":["Increases the heart rate","Slows the heart rate","Stops sweating","Closes all airways"],"answer":0,"explanation":"Sympathetic activity prepares the body for action and usually increases heart rate.","topic":"Autonomic function","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-034","question":"The kidneys contribute to long-term blood pressure regulation by controlling:","options":["Only body temperature","Fluid and sodium balance","Vision","Bile secretion"],"answer":1,"explanation":"Renal handling of sodium and water affects circulating volume and blood pressure.","topic":"Renal function","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-035","question":"Platelets are most directly involved in:","options":["Oxygen transport","Insulin production","Primary haemostasis and plug formation","Bile storage"],"answer":2,"explanation":"Platelets adhere and aggregate at an injured vessel to form the initial haemostatic plug.","topic":"Coagulation","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-036","question":"Which hormone raises blood glucose by stimulating glycogen breakdown?","options":["Insulin","Calcitonin","Oxytocin","Glucagon"],"answer":3,"explanation":"Glucagon promotes hepatic glycogen breakdown and glucose release.","topic":"Endocrine response","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-037","question":"Carbon dioxide is transported in blood predominantly as:","options":["Bicarbonate ions","Oxygenated haemoglobin only","Dissolved gas only","Glucose"],"answer":0,"explanation":"Most carbon dioxide is carried as bicarbonate after conversion in red blood cells.","topic":"Gas transport","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-038","question":"The main function of antibodies is to:","options":["Carry oxygen","Recognise specific antigens","Digest dietary fat","Produce urine"],"answer":1,"explanation":"Antibodies bind specific antigens and support immune defence.","topic":"Immune physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-039","question":"Osmosis is the movement of:","options":["Solute from high to low concentration only","Blood cells through arteries","Water across a selectively permeable membrane toward higher solute concentration","Air into the lungs"],"answer":2,"explanation":"Osmosis is water movement across a selectively permeable membrane down its water-potential gradient.","topic":"Fluid balance","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-040","question":"Pulse oximetry is used to estimate:","options":["Blood glucose","Serum sodium","Haemoglobin type","Peripheral oxygen saturation"],"answer":3,"explanation":"A pulse oximeter estimates arterial oxygen saturation non-invasively.","topic":"Vital signs","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"NUR-041","question":"Which molecule is commonly described as the immediate energy currency of cells?","options":["ATP","DNA","Urea","Bilirubin"],"answer":0,"explanation":"ATP stores and transfers usable energy for many cellular processes.","topic":"Energy metabolism","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-042","question":"The principal simple sugar measured in routine blood glucose testing is:","options":["Lactose","Glucose","Cellulose","Glycogen"],"answer":1,"explanation":"Glucose is the main circulating monosaccharide and a key cellular fuel.","topic":"Carbohydrates","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-043","question":"Proteins are built from smaller units called:","options":["Fatty acids","Nucleotides","Amino acids","Monosaccharides"],"answer":2,"explanation":"Amino acids join by peptide bonds to form proteins.","topic":"Proteins","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-044","question":"Most enzymes function by:","options":["Increasing activation energy","Being consumed in every reaction","Changing the final equilibrium","Lowering activation energy"],"answer":3,"explanation":"Enzymes accelerate reactions by lowering activation energy without being consumed.","topic":"Enzymes","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-045","question":"Iron is essential for haemoglobin because it:","options":["Binds oxygen reversibly in the haem group","Forms the cell membrane","Digests proteins","Stores glucose"],"answer":0,"explanation":"Ferrous iron in haem binds oxygen reversibly.","topic":"Haemoglobin","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-046","question":"Urea is formed mainly in the liver to help remove:","options":["Carbon dioxide from lungs","Excess nitrogen from amino-acid metabolism","Calcium from bone","Bile salts from intestine"],"answer":1,"explanation":"The urea cycle converts toxic ammonia into urea for renal excretion.","topic":"Nitrogen metabolism","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-047","question":"The main storage form of glucose in human liver and muscle is:","options":["Cellulose","Lactose","Glycogen","Cholesterol"],"answer":2,"explanation":"Glycogen is the principal storage polysaccharide in humans.","topic":"Glycogen","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-048","question":"Vitamin C is required for normal:","options":["Thyroid hormone storage","Bile production","Oxygen binding by iron","Collagen synthesis"],"answer":3,"explanation":"Vitamin C supports hydroxylation reactions needed for collagen formation.","topic":"Vitamin function","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-049","question":"Vitamin D helps maintain calcium balance mainly by increasing:","options":["Intestinal calcium absorption","Urinary calcium loss only","Red-cell destruction","Bile secretion"],"answer":0,"explanation":"Active vitamin D promotes intestinal calcium and phosphate absorption.","topic":"Vitamin D","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-050","question":"Albumin contributes significantly to:","options":["Oxygen synthesis","Plasma oncotic pressure","Platelet production","Bilirubin conjugation"],"answer":1,"explanation":"Albumin is the major plasma protein maintaining colloid oncotic pressure.","topic":"Plasma proteins","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-051","question":"Triglycerides are primarily used for:","options":["Carrying genetic information","Forming antibodies","Long-term energy storage","Producing urea"],"answer":2,"explanation":"Triglycerides store concentrated energy in adipose tissue.","topic":"Lipid metabolism","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-052","question":"Bilirubin is produced mainly during breakdown of:","options":["Insulin","Plasma glucose","Collagen","Haem from aged red blood cells"],"answer":3,"explanation":"Haem catabolism produces bilirubin, which is processed by the liver.","topic":"Bilirubin","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-053","question":"The principal extracellular cation is:","options":["Sodium","Potassium","Magnesium","Calcium"],"answer":0,"explanation":"Sodium is the main cation in extracellular fluid.","topic":"Electrolytes","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-054","question":"Bicarbonate in blood acts mainly as a:","options":["Digestive enzyme","Buffer","Hormone","Structural protein"],"answer":1,"explanation":"The bicarbonate-carbonic acid system buffers changes in blood pH.","topic":"Acid-base chemistry","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-055","question":"HbA1c gives an estimate of average blood glucose over approximately:","options":["One hour","One day","Several months","One week"],"answer":2,"explanation":"HbA1c reflects glycation over the lifespan of circulating red blood cells, roughly two to three months.","topic":"Diabetes monitoring","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-056","question":"Ketone bodies increase when the body relies heavily on:","options":["Protein synthesis after meals","Bile storage","Calcium absorption","Fat breakdown during low carbohydrate availability"],"answer":3,"explanation":"Ketone production rises when hepatic fatty-acid oxidation is increased.","topic":"Ketone bodies","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-057","question":"ALT is commonly measured as a marker associated with injury to the:","options":["Liver","Thyroid","Lung alveoli","Bone marrow"],"answer":0,"explanation":"Alanine aminotransferase is concentrated in hepatocytes and may rise with hepatocellular injury.","topic":"Liver enzymes","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-058","question":"Creatinine in blood is used clinically as part of assessing:","options":["Lung volume","Kidney filtration function","Thyroid size","Platelet adhesion"],"answer":1,"explanation":"Serum creatinine helps estimate glomerular filtration when interpreted with clinical context.","topic":"Renal markers","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-059","question":"A very high temperature can reduce enzyme activity because it may:","options":["Create extra active sites indefinitely","Turn proteins into DNA","Denature the enzyme's structure","Stop all molecular motion"],"answer":2,"explanation":"Heat can disrupt an enzyme's three-dimensional structure and active site.","topic":"Enzyme activity","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-060","question":"Glycolysis converts glucose primarily into:","options":["Urea","Bilirubin","Cholesterol","Pyruvate"],"answer":3,"explanation":"Glycolysis breaks glucose down to pyruvate while generating ATP and NADH.","topic":"Metabolic pathways","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"NUR-061","question":"An electronic health record (EHR) is best described as:","options":["A digital longitudinal record of a patient's health information","A public social-media profile","A device used only to measure temperature","A paper prescription archive"],"answer":0,"explanation":"An EHR organises patient information digitally across encounters and care settings.","topic":"Electronic health records","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-062","question":"Which action best protects a patient's electronic record from unauthorised viewing?","options":["Sharing a login with colleagues","Using an individual account with role-based access","Leaving the workstation unlocked","Sending screenshots to a personal email"],"answer":1,"explanation":"Individual accounts and role-based access help ensure that users see only information required for their role.","topic":"Privacy","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-063","question":"Multi-factor authentication requires:","options":["Two usernames","A password written on paper","Two or more different verification factors","A shared department password"],"answer":2,"explanation":"MFA combines different factors such as something known and something possessed.","topic":"Authentication","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-064","question":"A message asking a nurse to open an urgent unknown attachment and enter a password may be:","options":["A routine backup","A patient consent form","A laboratory calibration","A phishing attempt"],"answer":3,"explanation":"Phishing messages impersonate trusted senders to steal credentials or deliver malware.","topic":"Cybersecurity","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-065","question":"An EHR audit trail is used to record:","options":["Who accessed or changed information and when","Only the patient's blood group","The colour of a computer screen","Only deleted files"],"answer":0,"explanation":"Audit logs support accountability by recording access and changes to health information.","topic":"Audit trails","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-066","question":"Which practice most improves patient identification accuracy in a digital system?","options":["Searching by room number only","Using two approved patient identifiers","Reusing a previous patient's label","Using an abbreviated name without checking"],"answer":1,"explanation":"Two identifiers reduce the risk of selecting the wrong patient record.","topic":"Data quality","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-067","question":"Healthcare interoperability means that systems can:","options":["Operate only without internet","Replace all clinical judgement","Exchange and use health information in a meaningful way","Store images without labels"],"answer":2,"explanation":"Interoperability allows authorised systems to exchange and interpret information.","topic":"Interoperability","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-068","question":"FHIR is a healthcare standard primarily designed to support:","options":["Sterilisation of instruments","Measurement of blood pressure","Physical patient identification bands","Electronic exchange of healthcare information"],"answer":3,"explanation":"FHIR provides standardised resources and interfaces for exchanging health data.","topic":"Healthcare standards","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-069","question":"A PACS is commonly used to:","options":["Store and access medical images","Schedule staff leave only","Dispense medicines","Measure blood glucose"],"answer":0,"explanation":"Picture Archiving and Communication Systems manage storage and access to diagnostic images.","topic":"Imaging IT","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-070","question":"A laboratory information system (LIS) helps manage:","options":["Hospital catering orders","Specimen tracking and laboratory results","Ward furniture inventory only","Patient transport routes"],"answer":1,"explanation":"An LIS supports laboratory workflows, specimen identification, test processing and result reporting.","topic":"Laboratory IT","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-071","question":"If the hospital EHR becomes unavailable, staff should first:","options":["Share personal passwords","Stop documenting care","Follow the approved downtime procedure and use authorised paper workflows","Enter all records into an unapproved public app"],"answer":2,"explanation":"A downtime procedure preserves safe care and records until the system is restored.","topic":"Downtime planning","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-072","question":"Why are regular, tested backups important in healthcare IT?","options":["They replace user authentication","They make every email public","They prevent all human errors","They help restore data after system failure or ransomware"],"answer":3,"explanation":"Tested backups help recover critical information after data loss or cyber incidents.","topic":"Backups","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-073","question":"Before a telehealth consultation, staff should verify:","options":["Patient identity, consent and a private communication setting","Only the screen brightness","That the patient uses social media","That no clinical record is created"],"answer":0,"explanation":"Identity, consent and privacy are important parts of safe remote care.","topic":"Telehealth","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-074","question":"A clinical decision-support alert should be treated as:","options":["A command that always overrides the clinician","Information to be considered with clinical judgement","A replacement for patient assessment","A guaranteed diagnosis"],"answer":1,"explanation":"Decision support can assist clinicians but does not replace assessment or professional judgement.","topic":"Clinical decision support","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-075","question":"An electronic medication administration record (eMAR) is used to document:","options":["Only a patient's appointment history","Staff payroll","Medication orders and administration events","Radiology equipment maintenance"],"answer":2,"explanation":"An eMAR records medication administration and supports safer medication workflows.","topic":"Medication records","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-076","question":"Encryption helps protect information by:","options":["Automatically deleting incorrect records","Removing the need for consent","Making all passwords identical","Making data unreadable without the required key"],"answer":3,"explanation":"Encryption transforms data so that only authorised parties with the key can read it.","topic":"Data security","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-077","question":"The principle of least privilege means users receive:","options":["Only the minimum access needed for their duties","Administrator access by default","Access to every patient record","No access logging"],"answer":0,"explanation":"Least privilege reduces the exposure of sensitive information.","topic":"Least privilege","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-078","question":"If a staff member suspects a patient-data breach, they should:","options":["Delete all evidence","Report it promptly through the approved incident process","Post details in a group chat","Ignore it unless media report it"],"answer":1,"explanation":"Prompt reporting allows the organisation to contain, investigate and manage a possible breach.","topic":"Incident response","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-079","question":"Patient information should be shared externally only when:","options":["A colleague asks informally","The file is easy to download","There is a lawful, authorised purpose and appropriate safeguards","The recipient promises not to forward it"],"answer":2,"explanation":"Healthcare data sharing requires a justified purpose, authority and appropriate privacy safeguards.","topic":"Data sharing","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-080","question":"A good electronic clinical note should be:","options":["Written under another user's account","Altered without an audit trail","Filled with unexplained abbreviations","Accurate, timely, relevant and attributable to its author"],"answer":3,"explanation":"Good documentation is accurate, timely and clearly linked to the responsible professional.","topic":"Clinical documentation","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"NUR-081","question":"A patient says, 'I am worried about the test.' Which response is most empathetic?","options":["I understand this may feel worrying. What would you like me to explain?","There is nothing to worry about.","You should not ask questions.","Everyone has this test."],"answer":0,"explanation":"Acknowledging emotion and inviting questions supports patient-centred communication.","topic":"Patient communication","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-082","question":"Which instruction is clearest for a patient collecting a morning urine sample?","options":["Do the urine thing tomorrow.","Please collect the first urine you pass in the morning in the sterile container provided.","Bring something from the bathroom.","Collect it whenever you remember."],"answer":1,"explanation":"A clear instruction specifies timing, the sample and the approved container.","topic":"Clear instructions","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-083","question":"Choose the most appropriate phrase when asking a patient to confirm their date of birth.","options":["Tell me your birthday now.","You must know your date.","Could you please confirm your date of birth for me?","Say the date quickly."],"answer":2,"explanation":"Polite, direct wording is appropriate during identity checks.","topic":"Professional tone","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-084","question":"Choose the correct sentence.","options":["The results has been reviewed.","The results is reviewed yesterday.","The results was review.","The results have been reviewed."],"answer":3,"explanation":"The plural subject 'results' takes the verb 'have'.","topic":"Grammar","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-085","question":"The patient was admitted ___ the medical ward yesterday.","options":["to","in","at","on"],"answer":0,"explanation":"The usual phrase is 'admitted to the ward'.","topic":"Prepositions","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-086","question":"A 'discharge summary' is a document that usually:","options":["Lists only hospital staff salaries","Records key information about care and follow-up when a patient leaves hospital","Replaces informed consent","Contains only room numbers"],"answer":1,"explanation":"A discharge summary communicates the admission, treatment, status and follow-up plan.","topic":"Clinical vocabulary","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-087","question":"Which detail is most important in a referral letter?","options":["The writer's favourite treatment","A long unrelated personal story","The reason for referral and relevant clinical findings","The colour of the clinic"],"answer":2,"explanation":"A referral should state the purpose and relevant clinical information clearly.","topic":"Referral writing","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-088","question":"A note states: 'Review wound dressing in 48 hours.' When should the dressing be reviewed?","options":["Immediately","After two weeks","Only at discharge","Within two days"],"answer":3,"explanation":"Forty-eight hours equals two days.","topic":"Reading a note","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-089","question":"Which sentence is most appropriate when asking a patient to keep still during a procedure?","options":["Please try to remain still while I complete the procedure.","Don't move or you will cause trouble.","Keep quiet.","You are moving too much."],"answer":0,"explanation":"A courteous explanation gives the patient a clear and respectful request.","topic":"Polite request","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-090","question":"In the SBAR communication format, the letter 'A' stands for:","options":["Action","Assessment","Admission","Allergy"],"answer":1,"explanation":"SBAR stands for Situation, Background, Assessment and Recommendation.","topic":"Handover","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-091","question":"The phrase 'take the medicine twice daily' means:","options":["Take two tablets at once every week","Take it only when pain occurs","Take it two times each day","Take it every two hours"],"answer":2,"explanation":"Twice daily means two administrations per day; the dose and timing should also be specified.","topic":"Sentence meaning","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-092","question":"Which instruction is safest and clearest?","options":["Take two sometime.","Use as usual.","Take it when needed, maybe.","Take one tablet after breakfast and one after dinner."],"answer":3,"explanation":"Specific timing reduces the risk of misunderstanding.","topic":"Avoiding ambiguity","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-093","question":"A useful way to check whether a patient understands an instruction is to:","options":["Ask them to explain the plan in their own words","Repeat the same sentence louder","Assume they understand","Ask only a family member"],"answer":0,"explanation":"Teach-back helps confirm understanding without blaming the patient.","topic":"Active listening","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-094","question":"In a clinical note, 'monitor' most nearly means:","options":["Ignore","Observe and check regularly","Discharge immediately","Change the diagnosis"],"answer":1,"explanation":"To monitor is to observe or measure a condition over time.","topic":"Vocabulary","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-095","question":"Choose the correct sentence for a completed action.","options":["The sample is collected yesterday.","The sample collect yesterday.","The sample was collected yesterday.","The sample has collect yesterday."],"answer":2,"explanation":"The past simple passive 'was collected' describes a completed action.","topic":"Tense","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-096","question":"Which phrase is most appropriate before administering a medicine?","options":["I think this is probably yours.","Take it because I said so.","The label does not matter.","Let me confirm your identity and the medication details first."],"answer":3,"explanation":"Verification before administration is a key safety step.","topic":"Patient safety","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-097","question":"A professional referral letter should normally begin with:","options":["The recipient and purpose of the letter","An unrelated quotation","A list of abbreviations without context","The patient's social-media details"],"answer":0,"explanation":"Clear recipient details and purpose help the reader understand the referral immediately.","topic":"Letter structure","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-098","question":"A patient is advised to 'fast for 8 hours before the test.' What does this mean?","options":["Eat a large meal immediately before the test","Avoid food and drink as instructed for the eight-hour period","Exercise for eight hours","Take extra medication"],"answer":1,"explanation":"Fasting means following the specified restrictions on food and sometimes drink before testing.","topic":"Comprehension","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-099","question":"Which word best completes the sentence: 'Please ___ me if you experience dizziness.'","options":["informs","informing","inform","informed"],"answer":2,"explanation":"After 'please', use the base form of the verb.","topic":"Word choice","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"NUR-100","question":"Which explanation is most appropriate for a patient unfamiliar with a blood test?","options":["It is routine, so do not ask.","It is too technical to explain.","You will understand later.","The test uses a small blood sample to help us check your health. I can explain each step before we begin."],"answer":3,"explanation":"Plain language and an offer to explain support informed participation.","topic":"Clinical explanation","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"}]},"paramedical":{"label":"Paramedical","description":"Common five-subject healthcare syllabus at applied diagnostic and technical level. Original practice questions with 100 MCQs and 20 questions per subject.","difficulty_label":"Applied","subjects":[{"key":"anatomy","label":"Anatomy","question_count":20},{"key":"physiology","label":"Physiology","question_count":20},{"key":"biochemistry","label":"Biochemistry","question_count":20},{"key":"healthcare_it","label":"Healthcare IT","question_count":20},{"key":"oet_english","label":"OET-style Healthcare English","question_count":20}],"questions":[{"id":"PAR-001","question":"A standard axial CT image divides the body into which portions?","options":["Superior and inferior","Anterior and posterior","Right and left","Medial and lateral"],"answer":0,"explanation":"An axial plane divides the body into superior and inferior portions.","topic":"Imaging orientation","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-002","question":"The right lung normally has how many lobes?","options":["One","Three","Two","Four"],"answer":1,"explanation":"The right lung has superior, middle and inferior lobes.","topic":"Thoracic anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-003","question":"The renal cortex is located:","options":["Only inside the renal pelvis","Around the ureter","At the outer region of the kidney","Within the urinary bladder"],"answer":2,"explanation":"The renal cortex forms the outer region beneath the renal capsule.","topic":"Renal anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-004","question":"The common bile duct carries bile towards the:","options":["Urinary bladder","Oesophagus","Large intestine only","Duodenum"],"answer":3,"explanation":"The common bile duct delivers bile into the duodenum.","topic":"Hepatobiliary anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-005","question":"The coronary arteries primarily supply blood to the:","options":["Myocardium","Lung alveoli","Liver capsule","Kidney pelvis"],"answer":0,"explanation":"Coronary arteries supply oxygenated blood to the heart muscle.","topic":"Cardiac anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-006","question":"Cerebrospinal fluid is found in the:","options":["Pleural space","Ventricles and subarachnoid space","Peritoneal cavity","Bone marrow"],"answer":1,"explanation":"CSF circulates through the ventricles and subarachnoid space around the CNS.","topic":"Neuroanatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-007","question":"The hepatic portal vein connects the venous drainage of the gut to the:","options":["Lung","Heart valves","Liver","Thyroid gland"],"answer":2,"explanation":"The portal vein carries nutrient-rich blood from the gastrointestinal tract to the liver.","topic":"Vascular anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-008","question":"The pleural cavity is the potential space between the:","options":["Two lungs","Trachea and oesophagus","Ribs and sternum","Visceral and parietal pleura"],"answer":3,"explanation":"The pleural cavity lies between the visceral and parietal pleural layers.","topic":"Respiratory anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-009","question":"The spleen is located mainly in the:","options":["Left upper quadrant","Right iliac fossa","Pelvic cavity","Anterior neck"],"answer":0,"explanation":"The spleen lies in the left upper abdomen beneath the diaphragm.","topic":"Lymphatic anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-010","question":"The endocrine portion of the pancreas is organised into:","options":["Alveoli","Islets of Langerhans","Nephrons","Lymph follicles"],"answer":1,"explanation":"Pancreatic islets contain hormone-secreting endocrine cells.","topic":"Pancreatic anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-011","question":"A tendon connects:","options":["Bone to bone","Nerve to muscle","Muscle to bone","Cartilage to skin"],"answer":2,"explanation":"Tendons transmit force from muscle to bone.","topic":"Musculoskeletal anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-012","question":"Capillaries are specialised for exchange because they have:","options":["A thick muscular wall","No lumen","Multiple valves","A very thin endothelial wall"],"answer":3,"explanation":"A thin endothelial barrier supports exchange between blood and tissue.","topic":"Vascular anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-013","question":"The duodenum is the first part of the:","options":["Small intestine","Large intestine","Oesophagus","Stomach"],"answer":0,"explanation":"The duodenum receives gastric contents, bile and pancreatic secretions.","topic":"GI anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-014","question":"The glomerulus is located within the:","options":["Ureter","Renal corpuscle","Bladder wall","Adrenal medulla"],"answer":1,"explanation":"The glomerular capillary tuft sits inside Bowman's capsule in the renal corpuscle.","topic":"Urinary anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-015","question":"The adrenal glands sit:","options":["Inside the lungs","Behind the eyes","On the superior poles of the kidneys","Within the pancreas"],"answer":2,"explanation":"Each adrenal gland is positioned above a kidney.","topic":"Endocrine anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-016","question":"The prostate gland lies inferior to the:","options":["Kidneys","Liver","Diaphragm","Urinary bladder"],"answer":3,"explanation":"The prostate is located below the bladder and surrounds the proximal urethra.","topic":"Reproductive anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-017","question":"The thyroid gland is usually anterior to the:","options":["Trachea","Cerebellum","Spinal cord","Maxilla"],"answer":0,"explanation":"The thyroid lies in the anterior neck, adjacent to the upper trachea.","topic":"Head and neck","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-018","question":"The retina contains photoreceptors that detect:","options":["Sound","Light","Pressure in joints","Blood glucose"],"answer":1,"explanation":"Rods and cones in the retina convert light into neural signals.","topic":"Eye anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-019","question":"Haematopoietic stem cells in adults are mainly found in:","options":["Pleural fluid","Bile ducts","Red bone marrow","Cartilage"],"answer":2,"explanation":"Adult haematopoiesis occurs mainly in red marrow.","topic":"Haematology anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-020","question":"The pancreas is situated mainly:","options":["Inside the urinary bladder","Within the thoracic cavity","Anterior to the sternum","Posterior to the stomach"],"answer":3,"explanation":"The pancreas lies mostly retroperitoneally, posterior to the stomach.","topic":"Abdominal anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PAR-021","question":"Cardiac output is calculated as:","options":["Heart rate multiplied by stroke volume","Blood pressure divided by temperature","Respiratory rate multiplied by tidal volume","Haemoglobin multiplied by oxygen saturation"],"answer":0,"explanation":"Cardiac output equals heart rate multiplied by stroke volume.","topic":"Cardiac output","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-022","question":"The QRS complex on an ECG represents:","options":["Atrial depolarisation","Ventricular depolarisation","Ventricular repolarisation","SA node recovery only"],"answer":1,"explanation":"The QRS complex corresponds to ventricular depolarisation.","topic":"ECG physiology","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-023","question":"FEV1 measures the volume of air:","options":["Remaining after maximal expiration","Inhaled during quiet breathing","Exhaled forcefully in the first second","In the pleural space"],"answer":2,"explanation":"FEV1 is the forced expiratory volume exhaled in the first second.","topic":"Pulmonary function","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-024","question":"A reduced ventilation-perfusion ratio means an alveolar region has:","options":["More ventilation relative to perfusion","No blood supply in every case","No effect on oxygenation","Less ventilation relative to perfusion"],"answer":3,"explanation":"A low V/Q ratio means ventilation is low relative to perfusion.","topic":"Gas exchange","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-025","question":"Glomerular filtration is driven mainly by:","options":["Net pressure gradients across glomerular capillaries","Bile concentration","Skeletal muscle contraction","Skin temperature"],"answer":0,"explanation":"Hydrostatic and oncotic pressures determine net filtration pressure.","topic":"Renal physiology","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-026","question":"A primary rise in arterial carbon dioxide tends to cause:","options":["Respiratory alkalosis","Respiratory acidosis","Metabolic alkalosis","No pH change"],"answer":1,"explanation":"Increased CO2 increases carbonic acid and lowers blood pH.","topic":"Acid-base physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-027","question":"The PR interval on an ECG reflects conduction from the:","options":["Ventricles to the aorta","Lungs to the left atrium","Atria through the AV conduction system to the ventricles","Purkinje fibres to the skin"],"answer":2,"explanation":"The PR interval includes atrial depolarisation and AV nodal conduction time.","topic":"Cardiac physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-028","question":"A right shift of the oxyhaemoglobin dissociation curve indicates:","options":["Increased haemoglobin affinity for oxygen","No oxygen binding","Conversion of haemoglobin to albumin","Reduced affinity and easier oxygen unloading"],"answer":3,"explanation":"A right shift reduces oxygen affinity and facilitates tissue unloading.","topic":"Oxygen transport","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-029","question":"An isotonic solution generally causes red blood cells to:","options":["Maintain approximately their volume","Swell markedly","Shrink markedly","Burst immediately"],"answer":0,"explanation":"An isotonic extracellular solution produces no major net water shift.","topic":"Fluid physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-030","question":"The resting membrane potential of many neurons is maintained primarily by:","options":["Bile salts","Ion gradients and selective membrane permeability","Haemoglobin breakdown","Platelet aggregation"],"answer":1,"explanation":"Ion gradients, potassium permeability and the sodium-potassium pump maintain resting potential.","topic":"Neurophysiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-031","question":"Parathyroid hormone generally increases serum calcium by acting on:","options":["Lungs only","Skin glands only","Bone, kidney and indirectly intestine","Red blood cells only"],"answer":2,"explanation":"PTH affects bone and renal calcium handling and promotes active vitamin D formation.","topic":"Endocrine physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-032","question":"The main stimulus for ventilation in a healthy adult at rest is usually a rise in:","options":["Serum albumin","Plasma cholesterol","Bilirubin","Arterial carbon dioxide"],"answer":3,"explanation":"Central chemoreceptor responses to CO2-related pH changes are a major ventilatory drive.","topic":"Respiratory physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-033","question":"Fever involves an elevated hypothalamic temperature set point, often mediated by:","options":["Prostaglandin E2","Insulin","Haemoglobin","Bile"],"answer":0,"explanation":"Prostaglandin E2 contributes to raising the hypothalamic set point during fever.","topic":"Temperature physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-034","question":"Bile salts aid fat digestion by:","options":["Breaking peptide bonds","Emulsifying dietary fats","Digesting nucleic acids","Producing insulin"],"answer":1,"explanation":"Bile salts emulsify fats and support micelle formation for lipid absorption.","topic":"Digestive physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-035","question":"The loop of Henle contributes to urine concentration by establishing:","options":["A pulmonary pressure gradient","A cardiac electrical gradient","A medullary osmotic gradient","A bile salt gradient"],"answer":2,"explanation":"Countercurrent multiplication creates a medullary gradient used to concentrate urine.","topic":"Renal physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-036","question":"A prolonged activated partial thromboplastin time (aPTT) can reflect abnormality in the:","options":["Oxygen transport pathway","Renal filtration pathway","Bile production pathway","Intrinsic or common coagulation pathway"],"answer":3,"explanation":"aPTT assesses intrinsic and common pathway clotting factors.","topic":"Blood physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-037","question":"During ventricular systole, the mitral valve should be:","options":["Closed","Open","Absent","Partially removed"],"answer":0,"explanation":"The mitral valve closes during ventricular systole to prevent backflow into the left atrium.","topic":"Cardiac physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-038","question":"A rise in plasma osmolality normally stimulates:","options":["Bile secretion only","Thirst and ADH release","Insulin destruction","Reduced water conservation"],"answer":1,"explanation":"Osmoreceptors trigger thirst and ADH release to conserve water.","topic":"Osmoregulation","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-039","question":"Active transport differs from simple diffusion because it:","options":["Never uses membrane proteins","Always moves water only","Can move substances against a gradient using energy","Occurs only outside cells"],"answer":2,"explanation":"Active transport uses energy to move substances against an electrochemical gradient.","topic":"Cell physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-040","question":"The oxygen saturation measured by a pulse oximeter is an estimate of:","options":["Total lung capacity","Serum bicarbonate","Cardiac valve area","Haemoglobin oxygen saturation in pulsatile arterial blood"],"answer":3,"explanation":"Pulse oximetry estimates arterial haemoglobin oxygen saturation from light absorption.","topic":"Respiratory physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PAR-041","question":"A raised serum creatinine most directly suggests a possible reduction in:","options":["Glomerular filtration","Bile formation","Lung compliance","Platelet function"],"answer":0,"explanation":"Creatinine rises when renal clearance is reduced, though interpretation depends on context.","topic":"Renal marker","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-042","question":"ALT is generally more liver-specific than:","options":["Sodium","AST","Urea","Troponin"],"answer":1,"explanation":"ALT is more concentrated in hepatocytes than many extrahepatic tissues.","topic":"Liver marker","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-043","question":"Cardiac troponin is measured primarily to assess:","options":["Renal stone size","Thyroid volume","Myocardial injury","Lung capacity"],"answer":2,"explanation":"Cardiac troponin is a sensitive biomarker of myocardial injury.","topic":"Cardiac marker","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-044","question":"C-reactive protein (CRP) is best described as:","options":["A digestive enzyme","A clotting platelet","A bile pigment","An acute-phase protein"],"answer":3,"explanation":"CRP is produced by the liver in response to inflammatory signals.","topic":"Inflammation marker","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-045","question":"A fasting plasma glucose sample is used to assess:","options":["Glucose regulation","Serum calcium only","Liver imaging","Blood clotting time"],"answer":0,"explanation":"Fasting glucose is one laboratory measure used to evaluate glycaemic status.","topic":"Glucose testing","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-046","question":"A markedly low potassium level can affect:","options":["Only skin pigmentation","Cardiac electrical activity and muscle function","Bile colour","Bone length immediately"],"answer":1,"explanation":"Potassium is essential for membrane potentials in muscle and cardiac tissue.","topic":"Electrolytes","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-047","question":"A low bicarbonate with low pH is most consistent with:","options":["Metabolic alkalosis","Respiratory alkalosis","Metabolic acidosis","Normal acid-base status"],"answer":2,"explanation":"Low bicarbonate with acidemia suggests a primary metabolic acidosis.","topic":"Acid-base testing","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-048","question":"A low serum albumin may contribute to oedema because it reduces:","options":["Haemoglobin synthesis directly","Oxygen diffusion in alveoli","Platelet count","Plasma oncotic pressure"],"answer":3,"explanation":"Reduced albumin lowers plasma oncotic pressure and can favour fluid movement into tissues.","topic":"Proteins","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-049","question":"LDL cholesterol is often described clinically as:","options":["A lipoprotein associated with cholesterol delivery to tissues","The main blood glucose carrier","A clotting factor","A digestive hormone"],"answer":0,"explanation":"LDL transports cholesterol to peripheral tissues and is atherogenic when elevated.","topic":"Lipid profile","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-050","question":"Ferritin is most commonly used as an indicator of:","options":["Vitamin C stores","Iron stores","Serum sodium","Blood pH"],"answer":1,"explanation":"Ferritin reflects iron stores, though it can rise during inflammation.","topic":"Haematology chemistry","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-051","question":"A raised blood lactate may occur when:","options":["The patient has excess vitamin D only","Bile flow is increased","Tissue oxygen delivery is inadequate or metabolism is stressed","Platelets are elevated"],"answer":2,"explanation":"Lactate can rise with impaired tissue perfusion and several other metabolic stresses.","topic":"Lactate","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-052","question":"Alkaline phosphatase is commonly associated with pathology involving:","options":["Retina only","Skeletal muscle only","Hair follicles","Bile ducts or bone"],"answer":3,"explanation":"ALP is present in liver and bone; elevation must be interpreted with other tests.","topic":"Enzyme marker","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-053","question":"Unconjugated bilirubin is transported in plasma mainly bound to:","options":["Albumin","Fibrinogen","Insulin","Sodium"],"answer":0,"explanation":"Unconjugated bilirubin is poorly water-soluble and travels bound to albumin.","topic":"Bilirubin","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-054","question":"HbA1c is formed by non-enzymatic attachment of glucose to:","options":["Albumin only","Haemoglobin","Collagen","DNA"],"answer":1,"explanation":"HbA1c reflects glucose exposure through glycation of haemoglobin.","topic":"Glycated proteins","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-055","question":"The principal product of anaerobic glycolysis in human muscle is:","options":["Urea","Bilirubin","Lactate","Creatinine"],"answer":2,"explanation":"Under anaerobic conditions pyruvate is reduced to lactate to regenerate NAD+.","topic":"Metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-056","question":"Lipase is commonly measured when evaluating suspected:","options":["Iron deficiency","Thyroid storm","Anaemia","Acute pancreatitis"],"answer":3,"explanation":"Serum lipase is a useful biochemical marker in suspected acute pancreatitis.","topic":"Pancreatic marker","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-057","question":"Calcium is important for:","options":["Muscle contraction and coagulation","DNA replication only","Bile storage","Oxygen transport"],"answer":0,"explanation":"Calcium participates in muscle contraction, neurotransmission and coagulation.","topic":"Calcium","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-058","question":"Amino groups removed during amino-acid catabolism are ultimately converted largely into:","options":["Cholesterol","Urea","Bilirubin","Glycogen"],"answer":1,"explanation":"The liver converts ammonia from amino-acid catabolism into urea.","topic":"Protein metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-059","question":"Haemolysis of a blood sample can falsely increase measured:","options":["Sodium in all circumstances","Chloride only","Potassium","Bicarbonate always"],"answer":2,"explanation":"Cell rupture releases intracellular potassium and can produce a falsely high result.","topic":"Quality of specimen","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-060","question":"A competitive inhibitor usually binds to the enzyme's:","options":["Nucleus","Cell membrane only","Mitochondrial DNA","Active site"],"answer":3,"explanation":"Competitive inhibitors compete with substrate for the active site.","topic":"Enzyme kinetics","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PAR-061","question":"A laboratory information system (LIS) should link a specimen to:","options":["A unique patient and test order identifier","A technician's personal email","A ward colour only","An unverified handwritten nickname"],"answer":0,"explanation":"Unique identifiers support traceability from collection through reporting.","topic":"LIS workflow","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-062","question":"Scanning a specimen barcode at receipt helps reduce:","options":["The need for quality control","Patient and specimen identification errors","The need for trained staff","All laboratory variation"],"answer":1,"explanation":"Barcode scanning reduces manual transcription and identification errors.","topic":"Specimen barcoding","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-063","question":"DICOM is widely used for:","options":["Writing discharge prescriptions","Measuring blood pressure","Medical imaging data and communication","Patient diet planning"],"answer":2,"explanation":"DICOM defines formats and communication for medical imaging.","topic":"Imaging standard","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-064","question":"A radiology PACS allows authorised staff to:","options":["Issue pharmacy stock orders only","Record staff attendance","Replace radiologist reporting","Store, retrieve and view diagnostic images"],"answer":3,"explanation":"PACS manages image archiving and distribution.","topic":"PACS workflow","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-065","question":"HL7 standards are used to support:","options":["Exchange of healthcare information between systems","Instrument sterilisation","Clinical examination of reflexes","Blood sample centrifugation"],"answer":0,"explanation":"HL7 standards support healthcare data messaging and exchange.","topic":"Interoperability","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-066","question":"A laboratory system should support prompt escalation of:","options":["Every normal result by public notice","Critical or life-threatening results","Staff birthdays","Routine stationery requests"],"answer":1,"explanation":"Critical results require timely communication and documentation to support clinical action.","topic":"Critical result reporting","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-067","question":"An electronic quality-control log helps a laboratory:","options":["Avoid calibration forever","Change results without trace","Trend control results and identify shifts or trends","Remove instrument maintenance"],"answer":2,"explanation":"QC records help identify analytical problems before patient results are released.","topic":"Quality control","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-068","question":"A system audit trail is important because it:","options":["Automatically proves the clinical diagnosis","Replaces staff training","Deletes all previous results","Records user actions and changes to data"],"answer":3,"explanation":"Audit trails support traceability and accountability.","topic":"Audit","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-069","question":"A technician should access patient data:","options":["Only when required for assigned duties","Out of curiosity","To share with friends","Using another person's account"],"answer":0,"explanation":"Access should be limited to legitimate role-related needs.","topic":"Information privacy","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-070","question":"A suspicious link in a hospital email should be:","options":["Forwarded to all patients","Reported through IT/security procedures without opening it","Opened on a clinical workstation","Used to verify the sender's password"],"answer":1,"explanation":"Reporting suspicious messages helps prevent phishing and malware.","topic":"Cybersecurity","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-071","question":"During an LIS outage, specimen identity should be maintained using:","options":["Memory alone","Unlabelled tubes","The approved downtime procedure and unique identifiers","Shared spreadsheets on personal devices"],"answer":2,"explanation":"Approved downtime processes maintain traceability and safe reporting.","topic":"Downtime","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-072","question":"A backup is useful only if:","options":["It is never checked","It is stored on the same infected workstation only","No one knows where it is","It can be restored and its integrity is tested"],"answer":3,"explanation":"Restore testing confirms that backups are usable after a disruption.","topic":"Backup","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-073","question":"When a staff member changes role, system access should be:","options":["Reviewed and adjusted to match the new role","Left unchanged forever","Shared with the replacement","Removed from audit logs"],"answer":0,"explanation":"Role changes require access review to maintain least privilege.","topic":"Access management","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-074","question":"A result correction in an LIS should be:","options":["Overwritten without history","Traceable with an authorised amendment and audit record","Changed by any user","Communicated only verbally"],"answer":1,"explanation":"Traceable amendments preserve the original record and explain the correction.","topic":"Data integrity","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-075","question":"Secure image transfer for remote reporting requires:","options":["Public file-sharing links","Images without patient identifiers or controls","Authorised access and protected transmission","Personal messaging accounts"],"answer":2,"explanation":"Secure transfer protects patient confidentiality and image integrity.","topic":"Tele-radiology","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-076","question":"An electronic medical record differs from a paper chart because it:","options":["Removes the need for documentation","Automatically treats the patient","Guarantees zero data-entry errors","Stores clinical information in a searchable digital system"],"answer":3,"explanation":"Digital records improve access and organisation but still require accurate documentation.","topic":"Clinical systems","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-077","question":"A result flag generated by a clinical system should be:","options":["Reviewed in clinical context by an authorised professional","Accepted without verification in every case","Removed from the record","Used as the only diagnosis"],"answer":0,"explanation":"Flags support attention but require professional interpretation.","topic":"Decision support","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-078","question":"If ransomware is suspected on a workstation, staff should:","options":["Pay from a personal account","Disconnect or isolate it according to policy and report immediately","Continue entering patient data","Disable all security controls"],"answer":1,"explanation":"Prompt isolation and incident reporting can limit spread and support response.","topic":"Cyber incident","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-079","question":"Before sharing images for teaching or presentation, staff should check:","options":["Only whether the image looks clear","The patient's room number","Applicable consent, de-identification and institutional policy","The file name"],"answer":2,"explanation":"Patient images require privacy protection and appropriate authorisation.","topic":"Patient consent","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-080","question":"Before releasing a laboratory result electronically, the system should ensure:","options":["The screen is full-size","The computer has no mouse","A colleague has viewed the result informally","Correct patient, test, validation status and authorised release"],"answer":3,"explanation":"Identity matching and validation support safe electronic result release.","topic":"Result release","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PAR-081","question":"Which instruction best explains a fasting blood test?","options":["Do not eat for the specified period before the test; follow the clinic's advice about water and medicines.","Come whenever you like.","Eat a large breakfast first.","Stop all medicines without asking."],"answer":0,"explanation":"Clear instructions specify the fasting period and direct the patient to confirm medication advice.","topic":"Specimen instructions","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-082","question":"A patient asks why a sample must be labelled at the bedside. The best response is:","options":["It is just a hospital rule.","Labelling beside you helps us make sure the sample belongs to the correct patient.","The label is mainly for decoration.","We can identify it later."],"answer":1,"explanation":"Bedside labelling reduces the chance of a specimen being assigned to the wrong patient.","topic":"Patient preparation","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-083","question":"Which handover statement is most precise?","options":["The result looks a bit odd.","Someone should check a result later.","The potassium result is 6.4 mmol/L; I have repeated the patient and sample checks and am escalating it now.","The patient is probably fine."],"answer":2,"explanation":"A precise handover communicates the result, verification and immediate action.","topic":"Professional handover","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-084","question":"In a laboratory report, 'specimen' means:","options":["The test machine","The patient's appointment","The final invoice","The sample collected for testing"],"answer":3,"explanation":"A specimen is a sample of blood, urine or another material submitted for analysis.","topic":"Vocabulary","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-085","question":"Choose the grammatically correct sentence.","options":["The samples were received at 9 am.","The samples was received at 9 am.","The samples is received at 9 am.","The samples be received at 9 am."],"answer":0,"explanation":"The plural subject 'samples' takes 'were' in the past passive.","topic":"Grammar","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-086","question":"Which statement best explains a repeat sample request?","options":["You did it incorrectly.","Your sample was not suitable for this test, so we need to collect another one to obtain a reliable result.","The machine is always wrong.","We do not know what happened."],"answer":1,"explanation":"A neutral explanation gives the reason and next step without blaming the patient.","topic":"Clinical explanation","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-087","question":"Which phrase is most appropriate in a referral note?","options":["Do something about this patient.","The patient has a problem, maybe.","Please assess the patient for persistent shortness of breath and advise on further management.","This is not our responsibility."],"answer":2,"explanation":"A referral should state the clinical concern and the requested assessment clearly.","topic":"Referral language","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-088","question":"A report says 'repeat testing is advised due to a haemolysed sample.' What does this mean?","options":["The patient has confirmed anaemia.","The test was not ordered.","The result has been permanently deleted.","The sample may have been affected by red-cell breakdown and a new sample may be needed."],"answer":3,"explanation":"Haemolysis can affect some analytes; repeat testing may be required for a reliable result.","topic":"Comprehension","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-089","question":"Which sentence is best when asking a patient to provide a midstream urine sample?","options":["Please begin urinating, then collect the middle part of the stream in the sterile container.","Give us urine now.","Fill any bottle you can find.","Do not ask questions."],"answer":0,"explanation":"The instruction is specific and respectful, while identifying the correct collection method.","topic":"Polite request","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-090","question":"Which item should a laboratory report clearly include?","options":["Only the technician's initials","Patient identifiers, test name, result, units and relevant reference information","A nickname and no date","An unlabelled numerical value"],"answer":1,"explanation":"A report must identify the patient and test and make the result interpretable.","topic":"Written communication","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-091","question":"'Confidentiality' in healthcare refers to:","options":["Keeping all results secret from the patient","Avoiding all documentation","Protecting private patient information from unauthorised disclosure","Sharing information with anyone who asks"],"answer":2,"explanation":"Confidentiality protects patient information and limits disclosure to authorised purposes.","topic":"Vocabulary","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-092","question":"A patient says they do not understand a test result. The best response is:","options":["It is too complicated for you.","Just read the report.","Ask someone else.","Let me explain the result in everyday language and answer your questions."],"answer":3,"explanation":"Plain language and a willingness to answer questions support understanding.","topic":"Patient-centred language","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-093","question":"Choose the correct phrase: 'The report has been sent ___ the referring clinician.'","options":["to","for","at","with"],"answer":0,"explanation":"The correct construction is 'sent to the clinician'.","topic":"Grammar","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-094","question":"Which note is most objective?","options":["Patient is difficult.","Patient declined the procedure after the risks and benefits were explained.","Patient is careless.","Patient is not cooperative for no reason."],"answer":1,"explanation":"Objective documentation records observable events and relevant discussion without judgement.","topic":"Clinical note","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-095","question":"A test is scheduled for 'fortnightly' review. This means:","options":["Twice a day","Every two months","Every two weeks","Once a year"],"answer":2,"explanation":"A fortnight is a period of two weeks.","topic":"Time expression","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-096","question":"Which instruction is safest when a patient is unsure about stopping a medicine before a test?","options":["Stop it immediately.","Ask a neighbour.","Double the dose later.","Continue or stop it based on advice from the prescribing clinician or testing service."],"answer":3,"explanation":"Medication changes should be confirmed with the responsible clinician or testing service.","topic":"Safety communication","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-097","question":"A report says 'within reference interval'. This usually means the result:","options":["Falls within the laboratory's stated reference range","Confirms that no disease is present","Does not need clinical review ever","Was not measured"],"answer":0,"explanation":"A reference interval provides context but does not alone rule out all disease.","topic":"Reading a result","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-098","question":"Which opening is most appropriate when calling a ward about a critical result?","options":["Who is there?","Hello, this is the laboratory calling about a critical result for [patient identifier]. Could I speak to the responsible clinician?","You need to check a result now.","I am calling about a number."],"answer":1,"explanation":"The speaker identifies the service, purpose and patient using approved identifiers.","topic":"Polite telephone call","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-099","question":"Choose the best completion: 'The sample must be transported ___ the recommended temperature range.'","options":["between of","among","within","beside"],"answer":2,"explanation":"'Within the recommended temperature range' is grammatically correct and precise.","topic":"Word choice","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PAR-100","question":"After explaining a procedure, which question best checks understanding?","options":["You understand, yes?","Are you listening?","Do not forget what I said.","Can you tell me in your own words what will happen next?"],"answer":3,"explanation":"Teach-back checks understanding in a respectful, non-judgemental way.","topic":"Communication","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"}]},"pharmacy":{"label":"Pharmacy","description":"Common five-subject healthcare syllabus applied to medicines, pharmacy practice and patient safety. Original practice questions with 100 MCQs and 20 questions per subject.","difficulty_label":"Applied","subjects":[{"key":"anatomy","label":"Anatomy","question_count":20},{"key":"physiology","label":"Physiology","question_count":20},{"key":"biochemistry","label":"Biochemistry","question_count":20},{"key":"healthcare_it","label":"Healthcare IT","question_count":20},{"key":"oet_english","label":"OET-style Healthcare English","question_count":20}],"questions":[{"id":"PHA-001","question":"The median nerve passes through which structure at the wrist?","options":["Carpal tunnel","Cubital tunnel","Guyon canal","Radial groove"],"answer":0,"explanation":"The median nerve traverses the carpal tunnel beneath the flexor retinaculum.","topic":"Upper limb","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-002","question":"The deltoid muscle is primarily responsible for:","options":["Elbow extension","Shoulder abduction","Wrist flexion","Hip extension"],"answer":1,"explanation":"The deltoid is a major shoulder abductor, particularly after the initial range.","topic":"Anatomical landmark","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-003","question":"The trachea divides into the main bronchi at the:","options":["Epiglottis","Hilar ligament","Carina","Diaphragm"],"answer":2,"explanation":"The carina is the ridge at the tracheal bifurcation.","topic":"Thorax","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-004","question":"The portal triad is found within the:","options":["Round ligament of uterus","Greater omentum only","Falciform ligament only","Hepatoduodenal ligament"],"answer":3,"explanation":"The portal triad comprises the portal vein, hepatic artery and bile duct within the hepatoduodenal ligament.","topic":"Abdominal anatomy","difficulty":"easy","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-005","question":"The loop of Henle is part of the:","options":["Nephron","Collecting pelvis","Ureter","Renal capsule"],"answer":0,"explanation":"The loop of Henle is a segment of the nephron involved in establishing the medullary gradient.","topic":"Renal anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-006","question":"The urinary bladder is located primarily in the:","options":["Pleural cavity","Pelvic cavity","Cranial cavity","Pericardial cavity"],"answer":1,"explanation":"The urinary bladder lies in the pelvis when empty and expands superiorly as it fills.","topic":"Pelvis","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-007","question":"The parotid gland is located:","options":["Under the tongue","Behind the sternum","Anterior and inferior to the ear","Inside the orbit"],"answer":2,"explanation":"The parotid gland lies over the mandibular ramus, anterior and inferior to the ear.","topic":"Head and neck","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-008","question":"The optic nerve is cranial nerve:","options":["III","V","VII","II"],"answer":3,"explanation":"The optic nerve is the second cranial nerve and carries visual information.","topic":"Nervous system","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-009","question":"The sinoatrial node is located in the:","options":["Right atrium near the superior vena cava","Left ventricle apex","Interventricular septum","Coronary sinus only"],"answer":0,"explanation":"The SA node is in the right atrium near the opening of the superior vena cava.","topic":"Cardiac anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-010","question":"The right main bronchus is generally:","options":["Narrower and more horizontal","Wider, shorter and more vertical","Longer than the left","Absent in adults"],"answer":1,"explanation":"The right main bronchus is wider, shorter and more vertical, influencing aspiration patterns.","topic":"Respiratory anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-011","question":"The islets of Langerhans are located in the:","options":["Thyroid","Adrenal cortex","Pancreas","Pituitary"],"answer":2,"explanation":"The pancreatic islets contain endocrine cells including insulin- and glucagon-secreting cells.","topic":"Endocrine anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-012","question":"The patella is classified as a:","options":["Flat bone","Irregular bone","Pneumatic bone","Sesamoid bone"],"answer":3,"explanation":"The patella is a sesamoid bone embedded in the quadriceps tendon.","topic":"Musculoskeletal","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-013","question":"The major duodenal papilla receives the opening of the:","options":["Common bile and main pancreatic ducts (usually via ampulla)","Cystic duct only","Ureter","Hepatic vein"],"answer":0,"explanation":"The hepatopancreatic ampulla commonly opens at the major duodenal papilla.","topic":"GI anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-014","question":"The femoral artery is a continuation of the:","options":["Internal iliac artery","External iliac artery","Popliteal artery","Common carotid artery"],"answer":1,"explanation":"The external iliac artery becomes the femoral artery after passing beneath the inguinal ligament.","topic":"Vascular anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-015","question":"The thymus is most active in:","options":["Late adulthood only","Pregnancy only","Childhood","Old age only"],"answer":2,"explanation":"The thymus is prominent in childhood and undergoes involution after puberty.","topic":"Lymphatic anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-016","question":"The ciliary body contributes to:","options":["Auditory balance","Tear drainage only","Pupil pigmentation","Accommodation of the lens"],"answer":3,"explanation":"Ciliary muscle contraction changes zonular tension and lens curvature for accommodation.","topic":"Eye anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-017","question":"The vas deferens transports sperm from the:","options":["Epididymis toward the ejaculatory duct","Prostate to bladder","Urethra to kidney","Seminal vesicle to testis"],"answer":0,"explanation":"The vas deferens carries sperm from the epididymis toward the ejaculatory duct.","topic":"Reproductive anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-018","question":"The epidermis is primarily composed of:","options":["Simple columnar epithelium","Keratinised stratified squamous epithelium","Cardiac muscle","Dense cartilage"],"answer":1,"explanation":"The epidermis is keratinised stratified squamous epithelium.","topic":"Skin anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-019","question":"The medullary cavity of a long bone contains:","options":["Synovial fluid","Cerebrospinal fluid","Bone marrow","Bile"],"answer":2,"explanation":"The medullary cavity houses bone marrow.","topic":"Bone anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-020","question":"The intramuscular injection site in the ventrogluteal region avoids the major:","options":["Median nerve","Optic nerve","Phrenic nerve","Sciatic nerve"],"answer":3,"explanation":"The ventrogluteal site is selected to reduce risk to the sciatic nerve and major vessels.","topic":"Clinical anatomy","difficulty":"moderate","subjectKey":"anatomy","subjectLabel":"Anatomy"},{"id":"PHA-021","question":"Mean arterial pressure is influenced most directly by cardiac output and:","options":["Systemic vascular resistance","Body height alone","Serum bilirubin","Pulmonary volume"],"answer":0,"explanation":"MAP is approximately cardiac output multiplied by systemic vascular resistance.","topic":"Cardiovascular","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-022","question":"The majority of filtered sodium is reabsorbed in the:","options":["Collecting duct only","Proximal convoluted tubule","Bowman capsule","Ureter"],"answer":1,"explanation":"The proximal tubule reabsorbs most filtered sodium and water.","topic":"Renal physiology","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-023","question":"Aldosterone increases sodium reabsorption mainly in the:","options":["Glomerular capsule","Proximal oesophagus","Distal nephron","Alveoli"],"answer":2,"explanation":"Aldosterone acts on distal nephron principal cells to increase sodium reabsorption and potassium secretion.","topic":"Endocrine physiology","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-024","question":"A low arterial oxygen level is detected primarily by:","options":["Pancreatic islets","Hepatic stellate cells","Platelets","Peripheral chemoreceptors"],"answer":3,"explanation":"Carotid and aortic bodies respond to reduced arterial oxygen tension.","topic":"Respiratory physiology","difficulty":"easy","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-025","question":"Beta-1 adrenergic receptor stimulation typically increases:","options":["Heart rate and contractility","Bronchoconstriction","Gastric acid neutralisation","Insulin degradation"],"answer":0,"explanation":"Cardiac beta-1 receptors increase rate and contractile force when stimulated.","topic":"Autonomic physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-026","question":"Gastrin primarily stimulates:","options":["Insulin degradation","Gastric acid secretion","Bile storage","Renal filtration"],"answer":1,"explanation":"Gastrin promotes gastric acid secretion and mucosal growth.","topic":"GI physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-027","question":"Insulin promotes:","options":["Glycogen breakdown","Ketone production","Glycogen synthesis","Hepatic glucose release"],"answer":2,"explanation":"Insulin promotes glucose uptake and storage, including glycogen synthesis.","topic":"Metabolic regulation","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-028","question":"Thyroid hormones generally increase:","options":["Blood clotting time only","Bile storage","Urine pH only","Basal metabolic rate"],"answer":3,"explanation":"T3 and T4 increase metabolic activity and influence growth and development.","topic":"Thyroid physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-029","question":"A hypotonic extracellular solution tends to make cells:","options":["Swell","Shrink","Remain unchanged in all cases","Lose all protein"],"answer":0,"explanation":"Water moves into cells in a hypotonic environment, increasing cell volume.","topic":"Fluid physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-030","question":"The neurotransmitter released at the skeletal neuromuscular junction is:","options":["Dopamine","Acetylcholine","Serotonin","GABA"],"answer":1,"explanation":"Motor neurons release acetylcholine at nicotinic receptors on skeletal muscle.","topic":"Neurophysiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-031","question":"The primary function of erythropoietin is to stimulate:","options":["Platelet destruction","Bile secretion","Red blood cell production","Neutrophil apoptosis"],"answer":2,"explanation":"Erythropoietin from the kidneys stimulates erythropoiesis in bone marrow.","topic":"Haematology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-032","question":"The LH surge is responsible for triggering:","options":["Menstruation immediately","Implantation","Lactation","Ovulation"],"answer":3,"explanation":"The mid-cycle LH surge triggers ovulation.","topic":"Reproductive physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-033","question":"The plateau phase of the ventricular action potential is mainly associated with:","options":["Calcium influx through L-type channels","Rapid chloride loss only","Sodium-potassium pump stopping","Potassium influx only"],"answer":0,"explanation":"L-type calcium influx sustains the plateau phase in ventricular myocytes.","topic":"Cardiac electrophysiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-034","question":"Parathyroid hormone reduces renal reabsorption of:","options":["Calcium","Phosphate","Water in all segments","Glucose"],"answer":1,"explanation":"PTH promotes phosphate excretion by reducing proximal tubular phosphate reabsorption.","topic":"Renal regulation","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-035","question":"The Bohr effect describes reduced haemoglobin oxygen affinity with increased:","options":["Oxygen concentration","Plasma albumin","Carbon dioxide and hydrogen ion concentration","Calcium concentration"],"answer":2,"explanation":"Higher CO2 and H+ shift the dissociation curve right, aiding oxygen unloading.","topic":"Respiratory control","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-036","question":"Prostaglandins can increase pain sensitivity by:","options":["Blocking all sodium channels","Destroying sensory nerves","Inhibiting inflammation in every tissue","Sensitising peripheral nociceptors"],"answer":3,"explanation":"Prostaglandins sensitise nociceptors and contribute to inflammatory hyperalgesia.","topic":"Pain physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-037","question":"Sweating cools the body mainly through:","options":["Evaporation","Conduction from bone","Increased shivering","Vasoconstriction"],"answer":0,"explanation":"Evaporation of sweat removes heat from the skin.","topic":"Thermoregulation","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-038","question":"Baroreceptors are located mainly in the carotid sinus and:","options":["Pulmonary veins","Aortic arch","Renal pelvis","Portal vein"],"answer":1,"explanation":"Carotid sinus and aortic arch baroreceptors sense arterial wall stretch.","topic":"Blood pressure","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-039","question":"The migrating motor complex occurs mainly:","options":["Only during sleep paralysis","Only after bowel surgery","During fasting between meals","During swallowing alone"],"answer":2,"explanation":"The migrating motor complex is an interdigestive motility pattern that clears residual contents.","topic":"GI motility","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-040","question":"Tolerance to a drug refers to:","options":["An allergic response after one dose","A drug's expiry date","The fraction excreted unchanged","Reduced response after repeated exposure"],"answer":3,"explanation":"Tolerance is a reduced response after repeated administration, often requiring a higher dose for the same effect.","topic":"Drug response physiology","difficulty":"moderate","subjectKey":"physiology","subjectLabel":"Physiology"},{"id":"PHA-041","question":"Cytochrome P450 enzymes are important in:","options":["Drug metabolism","Oxygen transport only","Bone mineralisation only","Platelet aggregation"],"answer":0,"explanation":"CYP enzymes metabolise many drugs and other compounds, especially in the liver.","topic":"Pharmacological biochemistry","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-042","question":"A competitive enzyme inhibitor typically increases the apparent:","options":["Vmax","Km","Enzyme concentration","Product equilibrium constant"],"answer":1,"explanation":"Competitive inhibition increases apparent Km while Vmax can be reached at high substrate concentration.","topic":"Enzyme inhibition","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-043","question":"The major structural lipid component of cell membranes is:","options":["Triglyceride only","Cholesteryl ester only","Phospholipid","Free fatty acid only"],"answer":2,"explanation":"Phospholipids form the bilayer structure of biological membranes.","topic":"Lipid chemistry","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-044","question":"Disulfide bonds form between residues of:","options":["Glycine","Alanine","Valine","Cysteine"],"answer":3,"explanation":"Oxidation of cysteine thiol groups forms stabilising disulfide bonds.","topic":"Protein chemistry","difficulty":"easy","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-045","question":"Vitamin K is required for gamma-carboxylation of several:","options":["Coagulation factors","Thyroid hormones","Bile acids only","Plasma glucose molecules"],"answer":0,"explanation":"Vitamin K enables activation of factors II, VII, IX and X and proteins C and S.","topic":"Vitamins","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-046","question":"Phase II drug metabolism commonly involves:","options":["Only oxidation","Conjugation reactions","Passive filtration in glomerulus","Drug absorption in stomach"],"answer":1,"explanation":"Phase II reactions conjugate drugs or metabolites with polar groups to aid elimination.","topic":"Drug metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-047","question":"The pentose phosphate pathway produces NADPH and:","options":["Urea","Lactate only","Ribose-5-phosphate","Bile salts"],"answer":2,"explanation":"The pathway provides NADPH for reductive biosynthesis and ribose-5-phosphate for nucleotides.","topic":"Metabolic pathways","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-048","question":"An increased unconjugated bilirubin may occur with:","options":["Obstructive bile duct stone only","Reduced red cell destruction","Low haem synthesis only","Increased haemolysis"],"answer":3,"explanation":"Increased red-cell breakdown can raise unconjugated bilirubin production.","topic":"Clinical chemistry","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-049","question":"Severe hyperkalaemia is dangerous partly because it can cause:","options":["Cardiac conduction disturbances","Improved clotting","Increased haemoglobin synthesis","Reduced neuronal excitability only"],"answer":0,"explanation":"High extracellular potassium alters cardiac membrane potential and can provoke arrhythmias.","topic":"Electrolytes","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-050","question":"The Henderson-Hasselbalch equation relates pH to bicarbonate and:","options":["Serum calcium","Dissolved carbon dioxide","Haemoglobin concentration only","Chloride alone"],"answer":1,"explanation":"The bicarbonate buffer equation relates pH to bicarbonate and dissolved CO2.","topic":"Acid-base","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-051","question":"Gluconeogenesis occurs predominantly in the:","options":["Spleen","Skin","Liver","Red blood cells"],"answer":2,"explanation":"The liver is the principal site of gluconeogenesis, with the kidney contributing in prolonged fasting.","topic":"Carbohydrate metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-052","question":"Phenylketonuria is associated with impaired metabolism of:","options":["Tyrosine only due to iodine lack","Glycine","Histidine","Phenylalanine"],"answer":3,"explanation":"Classical PKU is usually due to phenylalanine hydroxylase deficiency.","topic":"Amino acid metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-053","question":"A spectrophotometer estimates analyte concentration by measuring:","options":["Light absorbance","Electrical resistance only","Sound frequency","Magnetic field strength"],"answer":0,"explanation":"Absorbance at an appropriate wavelength is related to concentration under defined conditions.","topic":"Biochemical testing","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-054","question":"Creatine kinase-MB has historically been associated with injury to:","options":["Kidney glomeruli","Cardiac muscle","Thyroid follicles","Pancreatic islets"],"answer":1,"explanation":"CK-MB can rise with myocardial injury, though cardiac troponin is preferred in most modern settings.","topic":"Enzyme marker","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-055","question":"A weak acid drug is generally more ionised in:","options":["Acidic solution","Pure lipid","Alkaline solution","A vacuum"],"answer":2,"explanation":"Weak acids donate protons more readily at higher pH and become more ionised.","topic":"Drug chemistry","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-056","question":"Glutathione helps protect cells by:","options":["Producing bile","Transporting oxygen","Breaking down DNA","Reducing reactive oxidants"],"answer":3,"explanation":"Reduced glutathione participates in antioxidant defence and peroxide detoxification.","topic":"Oxidative stress","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-057","question":"Albumin is synthesised mainly by the:","options":["Liver","Kidney","Spleen","Pancreas"],"answer":0,"explanation":"Hepatocytes synthesise albumin, a major plasma protein.","topic":"Liver function","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-058","question":"RNA differs from DNA because RNA normally contains:","options":["Thymine","Uracil","Deoxyribose only","No phosphate"],"answer":1,"explanation":"RNA contains uracil and ribose, whereas DNA contains thymine and deoxyribose.","topic":"Nucleic acids","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-059","question":"Transferrin transports:","options":["Calcium in bone","Glucose into cells","Iron in plasma","Bilirubin into urine"],"answer":2,"explanation":"Transferrin binds and transports ferric iron in the bloodstream.","topic":"Iron metabolism","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-060","question":"Procalcitonin may be used as an adjunct marker in assessment of:","options":["Bone fracture alignment","Renal stone location","Thyroid size","Bacterial infection"],"answer":3,"explanation":"Procalcitonin may support assessment of bacterial infection but should not replace clinical judgement.","topic":"Clinical markers","difficulty":"moderate","subjectKey":"biochemistry","subjectLabel":"Biochemistry"},{"id":"PHA-061","question":"A pharmacy information system should maintain an auditable record of:","options":["Prescription processing and dispensing","Staff personal social accounts","Patient entertainment preferences only","Unverified medicine stock"],"answer":0,"explanation":"Auditability supports safe prescribing, dispensing and traceability.","topic":"Pharmacy information systems","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-062","question":"Medication reconciliation is performed to:","options":["Automatically stop every chronic medicine","Compare current medicines with new orders and resolve discrepancies","Replace patient identity checks","Delete old prescriptions"],"answer":1,"explanation":"Reconciliation identifies omissions, duplications, dosing errors and unintended changes.","topic":"Medication reconciliation","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-063","question":"A safe electronic prescription should include:","options":["Only a medicine brand name","A prescriber's first name only","Patient identity, drug, dose, route and frequency","No date or patient identifier"],"answer":2,"explanation":"Complete prescription data reduces ambiguity and supports safe dispensing.","topic":"E-prescribing","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-064","question":"Barcode medication administration helps verify:","options":["The patient's diet preference only","Hospital building access","The prescriber's payroll","The right patient and medication at administration"],"answer":3,"explanation":"Barcode checks can support the medication rights when used with clinical verification.","topic":"Barcode medication administration","difficulty":"easy","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-065","question":"A pharmacy stock system should flag medicines approaching expiry to support:","options":["Stock rotation and reduction of expired products","Automatic dose escalation","Removal of batch numbers","Public release of patient records"],"answer":0,"explanation":"Expiry alerts support FEFO stock rotation and safe inventory management.","topic":"Inventory management","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-066","question":"A drug-interaction alert should be:","options":["Accepted blindly in every situation","Reviewed in patient context by an authorised clinician or pharmacist","Deleted without documentation","Shared publicly"],"answer":1,"explanation":"Clinical decision support assists but requires contextual professional review.","topic":"Drug interaction software","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-067","question":"Pharmacy staff should open a patient's medication profile only:","options":["Out of curiosity","To share with friends","For an authorised work-related purpose","Using another worker's login"],"answer":2,"explanation":"Role-based authorised access protects confidential health information.","topic":"Patient privacy","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-068","question":"Interoperability is valuable because it can:","options":["Make prescriptions anonymous to providers","Remove the need for validation","Guarantee no adverse drug events","Support exchange of medication and clinical information across systems"],"answer":3,"explanation":"Interoperability can reduce fragmentation when information is exchanged accurately and securely.","topic":"EHR interoperability","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-069","question":"A pharmacist receives an email asking to reset their password through an unfamiliar link. The safest action is to:","options":["Use the official portal and report the suspicious email","Click immediately","Forward the link to all patients","Reply with current credentials"],"answer":0,"explanation":"Using trusted routes and reporting phishing helps protect account security.","topic":"Cybersecurity","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-070","question":"An electronic dispensing audit trail records:","options":["Only the medicine colour","Who performed key actions and when","Patient's social-media username","The pharmacist's private messages"],"answer":1,"explanation":"Audit trails provide accountability and traceability for dispensing actions.","topic":"Clinical audit trails","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-071","question":"A duplicate patient profile can increase the risk of:","options":["Improved allergy checking","Automatic identity certainty","Incomplete or fragmented medication history","Reduced need for reconciliation"],"answer":2,"explanation":"Duplicate records may split allergies and medication data, increasing safety risk.","topic":"Data quality","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-072","question":"A remote pharmacy consultation should protect:","options":["Only the camera background","The internet speed alone","The pharmacy logo","Patient identity, consent and confidentiality"],"answer":3,"explanation":"Telepharmacy must preserve the same privacy and professional standards as in-person services.","topic":"Telepharmacy","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-073","question":"A pharmacy system backup should be:","options":["Regularly tested for restoration","Stored only on the live workstation","Never monitored","Accessible to every public user"],"answer":0,"explanation":"Tested backups support continuity after hardware failure or cyberattack.","topic":"Backup and recovery","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-074","question":"When a pharmacist leaves an organisation, their access should be:","options":["Kept active indefinitely","Revoked promptly","Shared with a new employee","Removed from the audit database"],"answer":1,"explanation":"Prompt deprovisioning prevents former staff from retaining unauthorised access.","topic":"Access control","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-075","question":"A digital batch and lot record helps support:","options":["Patient appointment reminders only","Staff attendance","Product recall and traceability","Unrelated laboratory calibration"],"answer":2,"explanation":"Batch traceability helps identify and locate affected products during a recall.","topic":"Batch traceability","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-076","question":"A medicine code system in an EHR helps improve:","options":["The colour of tablets","Internet connectivity","Clinical examination speed","Consistent identification of medicinal products"],"answer":3,"explanation":"Standardised medicine identifiers improve consistency in prescribing and data exchange.","topic":"Digital health standards","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-077","question":"A suspected dispensing system error should be:","options":["Reported and documented through the approved safety process","Hidden by changing the record","Ignored if the patient has left","Posted on social media"],"answer":0,"explanation":"Prompt incident reporting supports review, correction and prevention.","topic":"Incident reporting","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-078","question":"A high-dose warning in prescribing software should prompt the user to:","options":["Ignore all warnings","Check the order, patient factors and approved reference before proceeding","Increase the dose automatically","Delete the patient's allergy list"],"answer":1,"explanation":"Dose alerts require contextual review and appropriate clinical action.","topic":"Decision support","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-079","question":"Sending a prescription screenshot to a personal messaging group may:","options":["Improve access control","Create a valid clinical audit trail","Expose sensitive personal health information","Encrypt the record automatically"],"answer":2,"explanation":"Personal messaging may bypass approved safeguards and disclose confidential information.","topic":"Data protection","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-080","question":"During pharmacy software downtime, staff should use:","options":["A shared personal account","Memory without records","An unapproved public spreadsheet","The approved downtime and reconciliation procedure"],"answer":3,"explanation":"Approved downtime procedures protect dispensing safety and ensure later reconciliation.","topic":"System downtime","difficulty":"moderate","subjectKey":"healthcare_it","subjectLabel":"Healthcare IT"},{"id":"PHA-081","question":"Which phrase best checks a patient's understanding of a new medicine?","options":["Can you tell me how you will take this medicine at home?","You know this already, right?","Read the label and leave.","There is no need to ask questions."],"answer":0,"explanation":"Teach-back checks understanding in a respectful, patient-centred way.","topic":"Patient counselling","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-082","question":"Which instruction is least ambiguous?","options":["Take it often.","Take one tablet twice daily, in the morning and evening, as prescribed.","Use some tablets each day.","Take it when you remember."],"answer":1,"explanation":"Specific dose frequency and timing reduce interpretation errors.","topic":"Clear directions","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-083","question":"Which sentence is appropriate in a medication review note?","options":["The patient is careless.","The patient never listens.","The patient reports taking the medicine once daily instead of the prescribed twice-daily schedule.","The patient is difficult."],"answer":2,"explanation":"Objective documentation records what the patient reports without judgement.","topic":"Professional writing","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-084","question":"Choose the correct sentence.","options":["The pharmacist have checked the prescription.","The pharmacist were checked the prescription.","The pharmacist checking the prescription yesterday.","The pharmacist has checked the prescription."],"answer":3,"explanation":"A singular subject takes 'has' in the present perfect.","topic":"Grammar","difficulty":"easy","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-085","question":"'Contraindicated' most nearly means:","options":["Not recommended because of a specific risk or condition","Always required","Available without a prescription","Taken with food"],"answer":0,"explanation":"A contraindication is a reason a treatment should not be used in a particular situation.","topic":"Vocabulary","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-086","question":"A patient reports a possible side effect. The best opening is:","options":["That cannot be related.","Please describe what happened and when it started.","Stop everything immediately.","You should not complain."],"answer":1,"explanation":"Open questions invite relevant information and support safe assessment.","topic":"Counselling","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-087","question":"A medicine information leaflet should use:","options":["Unexplained abbreviations only","Long technical sentences for every patient","Clear language, headings and understandable instructions","No safety information"],"answer":2,"explanation":"Accessible language supports patient comprehension.","topic":"Written communication","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-088","question":"A label says 'Do not exceed 4 doses in 24 hours.' This means:","options":["Take four doses every hour.","Take one dose every four hours without limit.","Double the dose after a missed dose.","Use no more than four doses in one 24-hour period."],"answer":3,"explanation":"The label sets a maximum of four doses over any 24-hour period.","topic":"Reading comprehension","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-089","question":"Which request is most appropriate when confirming allergies?","options":["Could you tell me whether you have any medicine allergies or previous reactions?","You have no allergies, correct?","List them quickly.","Allergies do not matter."],"answer":0,"explanation":"Open, non-leading questions support accurate allergy history.","topic":"Polite request","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-090","question":"Which handover is clearest?","options":["There was a problem earlier.","The patient reports a rash two hours after the first dose; the medicine has been withheld pending clinical review.","The patient looks strange.","Someone should check later."],"answer":1,"explanation":"A concise handover states the event, timing and action taken.","topic":"Handover","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-091","question":"Complete the sentence: 'The prescription was reviewed ___ the pharmacist.'","options":["at","on","by","from"],"answer":2,"explanation":"The passive construction uses 'by' to identify the person who performed the action.","topic":"Preposition","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-092","question":"Which response is most empathetic when a patient is anxious about side effects?","options":["There is nothing to worry about.","Do not read the leaflet.","Everyone takes it.","It is understandable to be concerned. Let us discuss the benefits and possible risks."],"answer":3,"explanation":"Acknowledging concern and offering a discussion supports shared decisions.","topic":"Patient-centred language","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-093","question":"'Adherence' refers to:","options":["How closely medicine use follows an agreed treatment plan","The colour of a capsule","The medicine's price only","The number of pharmacy shelves"],"answer":0,"explanation":"Adherence describes the extent to which medicine-taking corresponds with an agreed plan.","topic":"Clinical terminology","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-094","question":"Choose the correct phrase: 'Please take this medicine ___ meals.'","options":["between of","after","among","beside to"],"answer":1,"explanation":"'After meals' is the correct prepositional phrase.","topic":"Grammar","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-095","question":"A referral for suspected adverse drug reaction should include:","options":["Only the patient's first name","A personal opinion without facts","Suspected medicine, dose, timing, symptoms and relevant history","No contact information"],"answer":2,"explanation":"Relevant details help the receiving clinician assess causality and severity.","topic":"Referral writing","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-096","question":"Which instruction is safest for a patient who misses a dose?","options":["Always take two doses next time.","Stop treatment permanently.","Take every missed dose together.","Follow the medicine-specific advice from the leaflet or prescriber; do not double a dose unless instructed."],"answer":3,"explanation":"Missed-dose instructions vary by medicine; doubling should not be assumed.","topic":"Clarity","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-097","question":"Choose the best word: 'Please ___ the medicine in its original labelled container.'","options":["keep","keeps","keeping","kept"],"answer":0,"explanation":"The base verb follows 'please'.","topic":"Word choice","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-098","question":"A medicine is labelled 'for external use only'. It should be:","options":["Taken orally with water","Applied to the body as directed and not swallowed","Injected","Stored in food"],"answer":1,"explanation":"External-use products are not for oral administration.","topic":"Comprehension","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-099","question":"Which is the best opening when calling a prescriber about a prescription discrepancy?","options":["Your prescription is wrong.","I need an answer now.","Hello, this is the pharmacist calling to clarify the dose written on the prescription for [patient identifier].","Who made this mistake?"],"answer":2,"explanation":"A professional opening identifies the caller, reason and patient using approved identifiers.","topic":"Telephone communication","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"},{"id":"PHA-100","question":"Which closing is appropriate after medicine counselling?","options":["You should already know this.","That is all; do not call again.","Ask someone else.","Please contact the pharmacy or your healthcare team if you have further questions."],"answer":3,"explanation":"A clear invitation for follow-up supports safe medicine use.","topic":"Professional tone","difficulty":"moderate","subjectKey":"oet_english","subjectLabel":"OET-style Healthcare English"}]}});
